static inline char16_t decodePercentEncoding(const char16_t *input)
{
    char16_t c1 = input[1];
    char16_t c2 = input[2];
    if (!isHex(c1) || !isHex(c2))
        return char16_t(-1);
    return decodeNibble(c1) << 4 | decodeNibble(c2);
